</Marquee>

import Marquee from "@marko-ui/shadcn/ui/marquee/marquee.marko";

static const LOGOS = ["Acme", "Globex", "Initech", "Umbrella", "Soylent", "Stark", "Wayne", "Wonka"];

<Marquee|logo| items=LOGOS speed=150 pauseOnInteraction class="w-full max-w-lg mx-auto">
  <span class="px-6 text-lg font-semibold text-muted-foreground">${logo}</span>
</Marquee>

import Marquee from "@marko-ui/shadcn/ui/marquee/marquee.marko";

static const LOGOS = ["Acme", "Globex", "Initech", "Umbrella", "Soylent", "Stark", "Wayne", "Wonka"];

<Marquee|logo| items=LOGOS side="top" pauseOnInteraction class="h-72 w-full max-w-xs mx-auto">
  <span class="px-4 py-6 text-lg font-semibold text-muted-foreground">${logo}</span>
</Marquee>

import Marquee from "@marko-ui/shadcn/ui/marquee/marquee.marko";

static const LOGOS = ["Acme", "Globex"];

<Marquee|logo| items=LOGOS autoFill pauseOnInteraction class="w-full max-w-lg mx-auto">
  <span class="px-6 text-lg font-semibold text-muted-foreground">${logo}</span>
</Marquee>
